    "he": "הַבֵּט לַבְּרִית כִּי מָלְאוּ מַחֲשַׁכֵּי אֶרֶץ נְאוֹת חָמָס׃",
    "refHe": "תהלים עד, כ",
    "book": "Tehilim (Salmos)",
    "chapter": 74,
    "verse": 20,
    "translation": "Olha para a aliança, pois os lugares escuros da terra estão cheios de moradas de violência.",
    "meaning": "É uma súplica por proteção diante da violência.",
    "kind": "contexto",
    "source": "https://he.wikisource.org/wiki/תהלים_עד_כ",
    "sourcePair": "https://he.wikisource.org/wiki/פסוק_המתחיל_ומסתיים_באות_ה_ס",
    "verified": true,
