    "id": 226,
    "pair": "כת",
    "he": "כֹּה אָמַר יְהֹוָה שִׁמְרוּ מִשְׁפָּט וַעֲשׂוּ צְדָקָה כִּי קְרוֹבָה יְשׁוּעָתִי לָבוֹא וְצִדְקָתִי לְהִגָּלוֹת׃",
    "refHe": "ישעיהו נו, א",
    "book": "Yeshayahu (Isaías)",
    "chapter": 56,
    "verse": 1,
    "translation": "Assim disse Hashem: guardem o direito e pratiquem a justiça, pois Minha salvação está perto de chegar e Minha justiça, de se revelar.",
    "meaning": "Esperança e prática da justiça caminham juntas.",
    "kind": "positivo",
    "source": "https://he.wikisource.org/wiki/ישעיהו_נו_א",
