    "he": "נְרַנְּנָה בִּישׁוּעָתֶךָ וּבְשֵׁם אֱלֹהֵינוּ נִדְגֹּל יְמַלֵּא יְהֹוָה כׇּל מִשְׁאֲלוֹתֶיךָ׃",
