    "he": "סָפְקוּ עָלַיִךְ כַּפַּיִם כׇּל עֹבְרֵי דֶרֶךְ שָׁרְקוּ וַיָּנִעוּ רֹאשָׁם עַל בַּת יְרוּשָׁלָ͏ִם הֲזֹאת הָעִיר שֶׁיֹּאמְרוּ כְּלִילַת יֹפִי מָשׂוֹשׂ לְכׇל הָאָרֶץ׃",
