    "he": "עִטַּרְתָּ שְׁנַת טוֹבָתֶךָ וּמַעְגָּלֶיךָ יִרְעֲפוּן דָּשֶׁן׃",
    "refHe": "תהלים סה, יב",
    "book": "Tehilim (Salmos)",
    "chapter": 65,
    "verse": 12,
    "translation": "Tu coroaste o ano com Tua bondade, e Teus caminhos transbordam fartura.",
