    "kind": "positivo",
    "source": "https://he.wikisource.org/wiki/משלי_כט_ו",
    "sourcePair": "https://he.wikisource.org/wiki/פסוק_המתחיל_ומסתיים_באות_ב_ח",
    "verified": true,
