    "book": "Yeshayahu (Isaías)",
    "chapter": 51,
    "verse": 4,
    "translation": "Presta atenção em Mim, Meu povo; Minha nação, escuta-Me. Pois de Mim sairá o ensinamento, e estabelecerei Minha justiça como luz para os povos.",
