    "kind": "positivo",
    "source": "https://he.wikisource.org/wiki/משלי_טז_יב",
    "sourcePair": "https://he.wikisource.org/wiki/פסוק_המתחיל_ומסתיים_באות_ת_א",
    "verified": true,
